<?php
/** Native social/ordering checks, only within the owned disposable discussion database. */
if(PHP_SAPI!=='cli'||!defined('KIWE_DISCUSSION_NATIVE_TEST')||!defined('KIWE_DISCUSSION_OWNED_DATABASE')||DB_NAME!==KIWE_DISCUSSION_OWNED_DATABASE)throw new RuntimeException('Owned discussion fixture required.');

function kiwe_discussion_reaction_tests(callable $check): void {
    global $wpdb;
    $service=new DSA\Discussion\Discussion_Service();$actions=new DSA\Discussion\Discussion_Reactions();
    $code=static fn($r)=>is_wp_error($r)?$r->get_error_code():'';
    $article=wp_insert_post(['post_title'=>'Reaction fixture','post_type'=>'post','post_status'=>'publish','comment_status'=>'open','post_author'=>1]);
    $other=wp_insert_post(['post_title'=>'Other reaction fixture','post_type'=>'post','post_status'=>'publish','comment_status'=>'open','post_author'=>1]);
    $known=get_user_by('email','proven@example.test')->ID;
    wp_set_current_user($known);
    $check(!DSA\Discussion\Discussion_Reaction_Store::install()&&!DSA\Discussion\Discussion_Reaction_Store::ready(),'Ordinary participants cannot create reaction storage');
    $read=$service->listing($article,0,0,'top');
    $check(!is_wp_error($read)&&$read['sort']==='latest'&&!DSA\Discussion\Discussion_Reaction_Store::ready(),'A public read degrades to native Latest without a schema write');
    wp_set_current_user(1);
    $check(DSA\Discussion\Discussion_Reaction_Store::install(),'An authorized maintenance action creates the indexed native-adjacent reaction store');
    add_action('wp_insert_comment',[DSA\Discussion\Discussion_Reactions::class,'native_insert'],20,2);
    add_action('transition_comment_status',[DSA\Discussion\Discussion_Reactions::class,'native_transition'],20,3);
    add_action('deleted_comment',[DSA\Discussion\Discussion_Reactions::class,'native_deleted'],20,2);
    add_action('deleted_user',static fn($id)=>DSA\Discussion\Discussion_Reaction_Store::delete_user((int)$id));
    $seed=static fn($post,$text,$parent=0)=>wp_insert_comment(['comment_post_ID'=>$post,'comment_author'=>'Public Reader','comment_author_email'=>'private-fixture@example.test','comment_content'=>$text,'comment_approved'=>1,'comment_parent'=>$parent,'comment_type'=>'comment']);
    $root=$seed($article,'Reaction root');$reply=$seed($article,'Reaction child',$root);
    $call=static function($post,$id,$kind,$enabled,$expected=null)use($actions,$service){$input=['kind'=>$kind,'enabled'=>$enabled,'actorKey'=>$service->current_actor_key()];if(null!==$expected)$input['expected']=$expected;return $actions->set($post,$id,$input);};
    wp_set_current_user(0);
    $check($code($call($article,$root,'like',true))==='kiwe_discussion_reaction_identity','A visitor cannot fabricate a like or contact-owned reaction');
    $unverified=get_user_by('email','unknown@example.test')->ID;wp_set_current_user($unverified);
    $check($code($call($article,$root,'like',true))==='kiwe_discussion_reaction_identity','Unverified sign-up alone does not permit unmoderated social reactions');
    wp_set_current_user($known);
    $liked=$call($article,$root,'like',true);$revision=$liked['revision'];
    $check(!is_wp_error($liked)&&$liked['reaction']['likes']===1&&$liked['reaction']['liked'],'A proven native account has one indexed like');
    $same=$call($article,$root,'like',true);
    $check(!is_wp_error($same)&&$same['reaction']['likes']===1&&$same['revision']===$revision,'Desired-state like retries are idempotent without redundant revision writes');
    $off=$call($article,$root,'like',false);
    $check(!is_wp_error($off)&&$off['reaction']['likes']===0&&!$off['reaction']['liked']&&$off['revision']!==$revision,'Unlike removes only the current account reaction');
    $check($code($call($other,$root,'like',true))==='kiwe_discussion_unavailable','A reaction cannot cross its native content target');
    wp_set_comment_status($root,'hold');
    $check($code($call($article,$reply,'like',true))==='kiwe_discussion_unavailable','Approved children of a held ancestor remain inaccessible to reactions');
    wp_set_comment_status($root,'approve');
    $check($code($actions->set($article,$root,['kind'=>'like','enabled'=>true,'actorKey'=>str_repeat('0',64)]))==='kiwe_discussion_actor','A reaction cannot borrow a stale actor after an account change');
    update_user_meta($known,'_kiwe_account_suspended','1');
    $check($code($call($article,$root,'like',true))==='kiwe_discussion_account','A suspended account cannot use its older verification to react');
    delete_user_meta($known,'_kiwe_account_suspended');
    $reported=$call($article,$root,'report',true);$reportedAgain=$call($article,$root,'report',true);
    $check(!is_wp_error($reported)&&!is_wp_error($reportedAgain)&&$reportedAgain['reaction']['reported']&&!isset($reported['reaction']['reports'])&&get_comment($root)->comment_approved==='1','A report is private, idempotent and leaves the moderation decision to the owner');
    wp_set_current_user(1);$moderation=DSA\Discussion\Discussion_Reactions::expected(get_comment($root));
    $hearted=$call($article,$root,'heart',true,$moderation);
    $check(!is_wp_error($hearted)&&$hearted['reaction']['hearted']&&$hearted['reaction']['moderation']['reports']===1&&get_comment_meta($root,DSA\Discussion\Discussion_Reactions::HEART,true)==='1','Business hearts are authorized institution markers; report totals remain staff-only');
    $check($code($call($article,$root,'heart',false,$moderation))==='kiwe_discussion_reaction_stale','An outdated moderation snapshot cannot overwrite a newer business action');
    wp_set_current_user($known);
    $check($code($call($article,$root,'heart',true,DSA\Discussion\Discussion_Reactions::expected(get_comment($root))))==='kiwe_discussion_reaction_identity','Knowing the action hash cannot grant a visitor the website team capability');
    wp_set_current_user(1);
    $roots=[$root];for($i=0;$i<14;++$i)$roots[]=$seed($article,'Top ordering fixture '.$i);
    foreach(array_slice($roots,0,3)as$id){$r=$call($article,$id,'pin',true,DSA\Discussion\Discussion_Reactions::expected(get_comment($id)));$check(!is_wp_error($r)&&$r['reaction']['pinned'],'Bounded native pin '.($id));}
    $check($code($call($article,$roots[3],'pin',true,DSA\Discussion\Discussion_Reactions::expected(get_comment($roots[3]))))==='kiwe_discussion_pin_limit','Pin capacity remains three under repeated fresh native reads');
    $check($code($call($article,$reply,'pin',true,DSA\Discussion\Discussion_Reactions::expected(get_comment($reply))))==='kiwe_discussion_pin_reply','Replies cannot occupy top-level pin positions');
    wp_set_current_user($known);$call($article,$roots[4],'like',true);
    $top=$service->listing($article,0,0,'top');
    if(is_wp_error($top))throw new RuntimeException('Native Top query refused: '.$top->get_error_code());
    $check(count($top['items'])===12&&array_slice(array_column($top['items'],'id'),0,3)===[$root,$roots[2],$roots[1]],'Top sorts pinned roots first, then business hearts, with deterministic ID ties');
    $check($top['nextCursor']!==''&&$top['nextBefore']===0,'Top uses a signed rank cursor instead of an incorrect ID-only cursor');
    $tail=$service->listing($article,0,0,'top',$top['nextCursor']);
    $check(!is_wp_error($tail)&&count($tail['items'])===3&&!array_intersect(array_column($top['items'],'id'),array_column($tail['items'],'id')),'Native rank pagination reaches all roots without duplicate pinned or popular records');
    $bad=substr($top['nextCursor'],0,-1).(str_ends_with($top['nextCursor'],'0')?'1':'0');
    $check($code($service->listing($article,0,0,'top',$bad))==='kiwe_discussion_cursor','Tampered rank cursors are refused');
    $check($code($service->listing($other,0,0,'top',$top['nextCursor']))==='kiwe_discussion_cursor','Rank cursors are bound to their native target');
    $call($article,$roots[5],'like',true);
    $check($code($service->listing($article,0,0,'top',$top['nextCursor']))==='kiwe_discussion_cursor_changed','A changed rank revision cannot silently reuse an inconsistent cursor');
    $latest=$service->listing($article,0,0,'latest');$older=$service->listing($article,0,$latest['nextBefore'],'latest');
    $check(!is_wp_error($older)&&count($older['items'])===3,'Latest keeps a stable native ID continuation while reactions change');
    $failedId=$roots[6];$oldRevision=DSA\Discussion\Discussion_Reactions::revision($article);$oldTimeout=(int)$wpdb->get_var('SELECT @@session.innodb_lock_wait_timeout');$oldSuspension=wp_suspend_cache_addition();
    $denyRevision=static fn($value,$object,$key)=>$key==='_kiwe_discussion_revision_v1'?false:$value;
    add_filter('update_post_metadata',$denyRevision,PHP_INT_MAX,3);$failed=$call($article,$failedId,'like',true);remove_filter('update_post_metadata',$denyRevision,PHP_INT_MAX);
    $check($code($failed)==='kiwe_discussion_reaction_write'&&!DSA\Discussion\Discussion_Reaction_Store::has($failedId,$known,'like')&&DSA\Discussion\Discussion_Reactions::revision($article)===$oldRevision,'Reaction and rank-revision failure rolls back together without a half-applied like');
    $check((int)$wpdb->get_var('SELECT @@session.innodb_lock_wait_timeout')===$oldTimeout&&wp_suspend_cache_addition()===$oldSuspension,'Owned discussion transactions restore native lock timeout and cache-addition state');
    $retry=$call($article,$failedId,'like',true);$check(!is_wp_error($retry)&&$retry['reaction']['likes']===1,'A failed reaction can be retried once storage recovers');
    $public=wp_json_encode($service->listing($article,0,0,'top'));
    $check(!str_contains($public,'user_id')&&!str_contains($public,'@')&&!str_contains($public,'"moderation"')&&!str_contains($public,'"reports"'),'Public discussion projections expose neither liker identities, contacts nor staff report controls');
    wp_set_current_user(1);$staff=wp_json_encode($service->listing($article,0,0,'top'));
    $check(str_contains($staff,'"moderation"')&&str_contains($staff,'"reports":1'),'Authorized staff receive action fingerprints and report totals in their private response');
    $deletable=$seed($other,'Reaction deletion fixture');wp_set_current_user($known);$call($other,$deletable,'like',true);wp_set_current_user(1);wp_delete_comment($deletable,true);
    $check(!$wpdb->get_var($wpdb->prepare('SELECT 1 FROM '.DSA\Discussion\Discussion_Reaction_Store::table().' WHERE comment_id=%d',$deletable)),'Native comment deletion removes its adjacent reaction rows');
    wp_set_current_user($known);
    $locker=new mysqli('127.0.0.1',DB_USER,DB_PASSWORD,DB_NAME,33067);
    $locker->begin_transaction();$lockId=$roots[7];$locker->query("SELECT comment_ID FROM {$wpdb->comments} WHERE comment_ID=".(int)$lockId.' FOR UPDATE');
    $oldErrors=$wpdb->suppress_errors(true);$started=microtime(true);
    try{$busy=$call($article,$lockId,'like',true);$elapsed=microtime(true)-$started;}finally{$locker->rollback();$locker->close();$wpdb->suppress_errors($oldErrors);}
    $check($code($busy)==='kiwe_discussion_reaction_storage'&&$elapsed<2.5&&!DSA\Discussion\Discussion_Reaction_Store::has($lockId,$known,'like'),'A real competing native row lock ends within a bounded wait without a false applied action');
    $check((int)$wpdb->get_var('SELECT @@session.innodb_lock_wait_timeout')===$oldTimeout&&wp_suspend_cache_addition()===$oldSuspension,'A timed-out mutation also restores native database and cache session state');
    require_once __DIR__.'/test-wordpress-discussion-privacy.php';kiwe_discussion_privacy_tests($check,$article,$root,$known,$seed);
    wp_set_current_user(1);
    $concurrent=$seed($other,'Concurrent pins root');$concurrentRoots=[$concurrent];for($i=0;$i<3;++$i)$concurrentRoots[]=$seed($other,'Concurrent pins '.$i);
    foreach(array_slice($concurrentRoots,0,2)as$id)$call($other,$id,'pin',true,DSA\Discussion\Discussion_Reactions::expected(get_comment($id)));
    update_option('cf23_reaction_concurrency_fixture',['post'=>$other,'roots'=>$concurrentRoots,'user'=>$known]);
}
